import json
with open('/root/autodl-tmp/eval_results/reeval_sdf_s2_l01_30k.json') as f:
    d = json.load(f)
if isinstance(d, list):
    tasks = {}
    for ep in d:
        task = str(ep.get('task', ep.get('task_name', ep.get('task_id', 'unknown'))))
        if task not in tasks:
            tasks[task] = {'success': 0, 'cf': 0, 'total': 0}
        tasks[task]['total'] += 1
        for sk in ['success', 'task_success', 'completed']:
            if sk in ep:
                if ep[sk]: tasks[task]['success'] += 1
                break
        for ck in ['collision', 'has_collision', 'collided']:
            if ck in ep:
                if not ep[ck]: tasks[task]['cf'] += 1
                break
    ts = 0; tc = 0; tt = 0
    for task, v in sorted(tasks.items()):
        tsr = v['success']/v['total']*100; car = v['cf']/v['total']*100
        print(f'{task}: TSR={tsr:.1f}%, CAR={car:.1f}% (n={v[\"total\"]})')
        ts += v['success']; tc += v['cf']; tt += v['total']
    print(f'OVERALL: TSR={ts/tt*100:.1f}%, CAR={tc/tt*100:.1f}% (n={tt})')
elif isinstance(d, dict):
    print(list(d.keys())[:20])
    import json as j
    print(j.dumps(d, indent=2)[:3000])
"

